actions.action:
tiles_applied_processes: f.tiles_applied_processes;

// Siete, ktorych pripady su INFRASTRUKTURA enginu, nie praca pouzivatela.
// Zoznam je ten isty ako vo vylucovacom dopyte zobrazenia "Vsetky pripady" -
// keby sa rozisli, "+" by ponukal siet, ktoru ten zoznam ani nezobrazuje.
def systemove = [
        "filter", "import_filters", "export_filters", "org_group",
        "impersonation_config", "impersonation_users_select",
        "preference_filter_item",
]

// Vsetky nasadene siete, kazda raz. `getAll()` vracia aj stare verzie, preto
// `unique()`; `allowedNets` je zoznam IDENTIFIKATOROV, nie stringId, takze
// verzia v nom nehra rolu.
def vsetkySiete = petriNetService.getAll()
        .collect { it.identifier as String }
        .unique()
        .sort()
def pouzivatelske = vsetkySiete.findAll { !(it in systemove) }

def vylucenie = systemove.collect { "processIdentifier:\"" + it + "\"" }.join(" OR ")

def views = [
        [id   : "general", icon: "folder",
         name : i18n("Všetky prípady", ["en": "All cases"]),
         query: "NOT (" + vylucenie + ")",
         nets : pouzivatelske],
        [id   : "general_system", icon: "settings",
         name : i18n("Všetky systémové prípady", ["en": "All system cases"]),
         query: "_exists_:processIdentifier",
         nets : vsetkySiete],
]

def postavene = []
views.each { v ->
    // `createOrUpdateMenuItem` z EtaskActionDelegate: 9 argumentov je PROJEKTOVA
    // varianta s funkcnou update cestou. Pri osmich si Groovy vyberie enginovu
    // (11 argumentov) a tá na update vola neexistujuce `updateFilter()`.
    def item = createOrUpdateMenuItem(
            v.id as String,
            "general",
            "Case",
            v.query as String,
            v.icon as String,
            v.name,
            v.nets as List,
            [:],
            [:]
    )
    if (item) {
        pripoj_do_uzla(item, "general")
        postavene << (v.id as String)
    }
}

// Uzol sa da konfigurovat AZ TERAZ. Na cistej databaze v tejto chvili este
// neexistoval - vyrobil ho `createOrUpdateMenuItem` vyssie (vola `createUri`).
// Kym to stalo v udalosti `upload`, backend na cistej databaze NENASTARTOVAL:
// `setUriNodeData` spadol na NullPointerException z vnutra Groovy a NetRunner
// zhodil cely kontext. Na uz beziacej instancii to bolo neviditelne, lebo uzol
// tam z minula bol.
setUriNodeData("general", "General", null, "folder")
setUriNodeDataFilters("general", ["general"])

// AZ NAKONIEC. Runner berie toto pole ako "katalog uz je postaveny pre tieto
// siete" - keby sa zapisalo skor a stavanie polozky spadlo, dalsi start by
// katalog povazoval za hotovy a uz by ho neopravil.
change tiles_applied_processes value { vsetkySiete.join(",") }
changeCaseProperty("title").about {
    "Katalóg – " + postavene.size() + "/" + views.size() +
            ", " + pouzivatelske.size() + " procesov"
}
